PREFIX proveedores: <https://w3id.org/rastro/proveedores#>
SELECT ?n WHERE {
  { SELECT ?g (SUM(?m) AS ?total) WHERE {
      ?c a proveedores:Contract ; proveedores:supplier ?s ; proveedores:amount ?m ; proveedores:sector ?sec .
      ?sec proveedores:within ?x . ?x proveedores:code "5415" .
      ?s proveedores:group ?g .
    } GROUP BY ?g }
  ?g proveedores:name ?n .
} ORDER BY DESC(?total) LIMIT 5
